let left_x, right_x, top_y, bottom_y, resolution;
let num_colums, num_rows;
let grid = [];
let default_angle, angle;
let space;
let xoff = 0.1;
let yoff = 0.1;

function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  left_x = int(width * -2.5);
  right_x = int(width * 2.5);
  top_y = int(height * -2.5);
  bottom_y = int(height * 2.5);
  resolution = int(width * 0.005);
  num_columns = (right_x - left_x) / resolution;
  num_rows = (bottom_y - top_y) / resolution;
  space = 2;
  for (let x = 0; x < num_columns; x++) {
    grid[x] = [];
    for (let y = 0; y < num_rows; y++) {
      let angle = (y / num_rows) * (x / num_columns) * PI * 32;
      grid[x][y] = angle + random(-0.5, 0.5);
    }
  }
  // pixelDensity(5);
  background(0, 0, 95, 100);
}

function draw() {
  let x = random(-width / 2, width * 1.5);
  let y = random(-height / 2, height * 1.5);
  let step_length = random(10,16);
  beginShape();
  for (var i = 0; i < step_length; i++) {
    noFill();
    strokeCap(SQUARE);
    if (x < 300 && y < 300 && x + y <= 300) {
      strokeWeight(random(1.2, 3.8));
      stroke(random(240, 280), random(45, 90), 95, random(45, 65));
    } else if (x > 200 && y > 200 && x + y >= 200 + height) {
      strokeWeight(random(1.8, 2.8));
      stroke(random(240, 280), random(45, 90), 95, random(35, 55));
    } else {
      strokeWeight(random(2.2, 4.8));
      stroke(random(220, 310), random(45, 90), 95, random(45, 85));
    }
    curveVertex(x, y);
    let x_offset = x - left_x;
    let y_offset = y - top_y;
    let column_index = int(x_offset / resolution);
    let row_index = int(y_offset / resolution);
    grid_angle = grid[column_index][row_index];
    let x_step = map(noise(xoff,yoff),0,1,-2,2) * step_length * 0.1 * sin(grid_angle) - 25;
    let y_step = map(noise(xoff,yoff),0,1,-2,2)* step_length * 0.2 * atan(grid_angle) - 10;
    let t = random(0.75, 1.2);
    x = lerp(x, x + x_step, t);
    y = lerp(y, y + y_step, t);

    xoff += random(-0.25, 0.25);
    yoff += random(-0.25, 0.25);

    circle(x+xoff,y+yoff,random(5));
  }
  endShape();

}

